import json
from typing import Any, List


def get_elements_by_diagnosis1(data: Any, diagnosis_name: str) -> List:
    results = []

    def search(node: Any):
        if isinstance(node, dict):
            if diagnosis_name in node and isinstance(node[diagnosis_name], dict):
                elements = node[diagnosis_name].get("elements")
                if elements:
                    results.extend(elements)
            for v in node.values():
                search(v)
        elif isinstance(node, list):
            for item in node:
                search(item)

    search(data)
    return results


def get_desc_by_key1(request):
    # Загружаем JSON из файла
    with open("diagnoses.json", "r", encoding="utf-8") as f:
        data = json.load(f)

    elements = get_elements_by_diagnosis1(data, request)
    return elements


# text = "**Оптическая коррекция миопии**  \n**Варианты подбора:**  \n- Очки, контактные и ортокератологические (ночные) линзы.\n- Выбор вида коррекции зависит от возраста, степени близорукости, комфортности и возможных противопоказаний.\n\n**Основные показания для оптической коррекции:**  \n- Снижение “не скорректированной” (без очков) бинокулярной остроты зрения.\n- Признаки зрительного утомления, косоглазие, выраженная скрытая склонность к расхождению глаз, врождённая близорукость.\n\n**Учет при подборе:**  \n- Степень миопии, функция аккомодации (способность менять фокус), конвергенция (сведение глаз при взгляде вблизи), бинокулярное зрение.\n\n**Современные типы очков:**\n1. **Трансфокальные линзы** — сочетают обычную коррекцию и равномерное усиление преломления по периферии для формирования периферического миопического дефокуса. Это снижает скорость удлинения оси глаза и тормозит прогрессирование миопии.\n   - Через 4–5 лет: у 37,5% — стабилизация, у 3,6% — улучшение, в остальных — прогресс продолжается, но медленнее, чем без таких очков.\n2. **Линзы с кольцами высокоасферичных микролинз и/или множественными дефокусными сегментами** — создают замедляющий сигнал перед сетчаткой и замедляют прогрессирование до 67–79% по сравнению с обычными однофокусными очками.\n3. **Рекомендуется назначать полную коррекцию по результатам обследования на расширенном (парализованном) зрачке — циклоплегической рефракции. Гипокоррекция допустима не более чем на 0,5 дптр, если обычная коррекция плохо переносится.**\n\n**Особые методы коррекции:**\n- **Альтернирующая анизокоррекция** (чередующийся миопический дефокус на двух глазах) для детей 7–11 лет с прогрессирующей миопией до 2,5 дптр и определёнными формами косящих и “ровно стоящих” глаз.\n- **Очки с аддидацией** (добавками +0,75–3,0 дптр) для детей со сниженной аккомодацией и склонностью к эзофории.\n- **Ранняя коррекция врождённой миопии** — начиная с 1 года жизни. Слабее на 2 дптр “сферой”, астигматизм максимально корректировать, разницу между глазами — тоже максимально устранять (до 6 дптр); по возможности — контактные линзы.\n\n**Опция для взрослых:**  \n- Очки и/или контактные линзы для дали, с учетом удобства.\n- Для работы вблизи — очки с аддидацией (“плюсом”).\n  \n**Контактные линзы:**  \n- Однофокальные — при врождённой миопии, амблиопии/без неё, высокой анизометропии.\n- Мультифокальные/бифокальные линзы или линзы с миопическим дефокусом — детям с прогрессирующей близорукостью.\n\n**Ортокератологические линзы (ОКЛ):**  \n- Жёсткие линзы, надеваемые на ночь, временно изменяют форму роговицы, обеспечивая хорошее дневное зрение и замедляя удлинение глаза.\n- Рекомендованы при миопии до −8,0 дптр и астигматизме до 5,0 дптр, особенно при быстром прогрессировании.\n\n**Противопоказания для ОКЛ:**  \n- Острые воспаления, тяжёлый “сухой глаз”, дистрофии и изъязвления роговицы, нарушения анатомии глаз или орбиты, онкология, психогенные проблемы, невозможность соблюдать рекомендации по уходу.\n\n**Резюме по смыслу:**  \nЦель оптической коррекции миопии — не только коррекция зрения, но и торможение прогрессирования за счёт технологий воздействия на периферическую рефракцию. Применение специальных линз (очковых, контактных, ортокератологических) показано прежде всего детям с риском прогрессирования или уже прогрессирующей миопией. Подбор и вариант коррекции индивидуальны, требует периодического контроля офтальмолога."
